const q2={q:'A uniform horizontal 3.00 m beam weighs 180 N. A 420 N sign hangs at its end, which is supported by a cable at 40.0° above horizontal pulling leftward. Find cable tension and signed hinge components.',points:['Moments about hinge: T sin40° × 3.00 = 180 × 1.50 + 420 × 3.00.','Tᵧ = 510 N and T = 510/sin40° ≈ 793 N.','Hₓ = T cos40° = 510 cot40° ≈ 608 N right.','Hᵧ = 180 + 420 − 510 = 90.0 N up.','Check force sums and recognise that cable tension differs from its vertical component.']};s.practice=[q1,q2];
A(3,'Independent: asymmetric cable support',question(q1),'practice');
A(3,'Independent: beam and sign',question(q2),'practice');
