// Core relativity: define a frame and identify proper quantities before applying gamma.
{
const s=make('relativity-clock-length-scenarios','relativity-effects','Relativity: clocks, spacecraft and particle lifetimes','Clocks & lengths','Identify proper time and proper length; reconcile approaching, receding and particle scenarios.'),A=s.add;s.constants='Use c = 3.00 × 10⁸ m/s. Frames move inertially at constant relative velocity unless stated. β = |v|/c and γ = 1/√(1 − β²).';
function frames(){return marker('Two inertial frames: Earth laboratory S and spacecraft S prime with their own clocks and rulers',line(70,320,680,320)+arrow(85,320,85,75,'#0b8774')+text(105,90,'S: Earth laboratory')+text(120,285,'Earth clock and ruler')+'<rect x="300" y="140" width="270" height="95" rx="20" fill="#e6eff7" stroke="#2a6bb2" stroke-width="3"/>'+arrow(590,185,700,185,'#2a6bb2')+text(320,175,'S′: spacecraft')+text(320,210,'ship clock and ruler')+text(605,155,'v →')+text(70,410,'State which observer measures each time, length and velocity.'));}
function clock(){return marker('Light clock: vertical path in its rest frame and diagonal path in a frame where it moves','<rect x="80" y="80" width="130" height="200" fill="#e6eff7"/>'+line(100,100,190,100)+line(100,260,190,260)+arrow(145,260,145,100,'#0b8774')+text(65,55,'Clock rest frame')+text(65,320,'shorter light path')+line(380,100,660,100)+line(330,260,610,260)+arrow(355,260,505,100,'#2a6bb2')+arrow(505,100,655,260,'#2a6bb2')+text(360,55,'Clock moving in lab')+text(345,320,'longer diagonal path')+text(75,415,'Same c in both frames; the longer path requires more lab time.'));}
function muon(){return marker('Muon journey described in two frames: Earth sees a dilated lifetime; muon sees a contracted atmosphere','<rect x="100" y="85" width="210" height="220" fill="#e6eff7" stroke="#2a6bb2"/>'+arrow(205,105,205,285,'#c87518')+text(85,55,'Earth frame')+text(85,350,'Atmosphere thickness L₀')+'<rect x="440" y="190" width="210" height="115" fill="#e8f5ef" stroke="#0b8774"/>'+arrow(545,285,545,210,'#2a6bb2')+text(425,55,'Muon rest frame')+text(425,350,'Contracted thickness L₀/γ')+text(75,415,'Both frames agree whether the particle reaches the detector.'));}
const gamma=b=>1/Math.sqrt(1-b*b);
function relativityLab(){return '<div class="pp-sim" data-rel-lab><label>Relative speed as a fraction of c <input type="range" min="0" max="99" value="60" step="1"><output></output></label><div class="pp-sim-readout pp-scenario-readout" aria-live="polite"></div><p>Proper clock interval: 1.00 s. Proper spacecraft length: 100 m. The moving clock interval is γ seconds and the longitudinal moving length is 100/γ metres.</p></div>';}
const previous=s.wire;s.wire=root=>{previous(root);root.querySelectorAll('[data-rel-lab]').forEach(el=>{const input=el.querySelector('input');function update(){const b=+input.value/100,g=gamma(b);el.querySelector('output').textContent=b.toFixed(2)+'c';el.querySelector('.pp-sim-readout').textContent='γ = '+g.toFixed(3)+' · moving-clock interval = '+g.toFixed(3)+' s · moving length = '+(100/g).toFixed(2)+' m';}input.oninput=update;update();});};
A(0,'Whose clock is being read?',frames()+P('“The journey takes 10 years” is incomplete at relativistic speed. Ten years on the spacecraft clock and ten years in the Earth frame can describe different measurements of the same journey.'));
A(0,'Define an inertial frame',P('An inertial observer moves at constant velocity without acceleration. Earth and a steadily coasting spacecraft can be treated as approximately inertial for a suitable problem. A turning or accelerating spacecraft needs additional care.'));
A(0,'Keep the two postulates together',P('The laws of physics have the same form in all inertial frames. Every inertial observer measures the same vacuum speed of light, c. These statements require time and longitudinal length measurements to depend on the frame.'));
A(0,'Coordinate measurements versus what your eyes see',P('A measured interval in an inertial frame uses properly synchronised clocks and accounts for signal travel time. The rate at which light signals arrive at an eye also depends on approach or recession. That visual effect is not simply the time-dilation equation.'));
A(0,'Direction does not change γ',E('γ = 1/√(1 − v²/c²)')+P('v is squared. A spacecraft approaching at 0.60c and one receding at 0.60c have the same Lorentz factor relative to Earth. Direction matters for positions and arriving signals, but not for this factor.'));
A(0,'Proper time belongs to one clock',E('Δτ = proper time')+P('Proper time between two events is measured by a clock present at both events, so those events occur at the same position in that clock’s rest frame. A particle’s creation and decay define its proper lifetime.'));
A(0,'Proper length belongs to the rest frame',E('L₀ = length in the object’s rest frame')+P('Measuring a moving object’s length requires the positions of its two ends at the same time in the measuring frame. A photograph is not automatically that measurement.'));
A(0,'A light-clock explanation',clock()+P('In the clock rest frame the light goes up and down. A frame in which the clock moves sees a diagonal path. Since c is unchanged, the longer path takes more time.'));
A(1,'Calculate the Lorentz factor',E('β = |v|/c<br>γ = 1/√(1 − β²)')+P('At 0.60c, γ = 1/√0.64 = 1.25. γ is dimensionless and at least 1 for a material object moving below c.'));
A(1,'Time-dilation relationship',E('Δt = γΔτ')+P('Δτ is the interval on the clock that is present at both events. Δt is the longer interval assigned by the frame in which that clock moves. Identify these roles before substituting.'));
A(1,'Length-contraction relationship',E('L = L₀/γ')+P('L₀ is the proper length. L is the shorter longitudinal length in a frame where the object moves. Do not multiply L₀ by γ.'));
A(1,'Only the parallel dimension contracts',P('A 100 m spacecraft moving along its length is measured shorter longitudinally. Its width and height perpendicular to the relative velocity are unchanged by the simple length-contraction relationship.'));
A(1,'Approaching and receding measurements',P('For the same speed magnitude, either direction gives the same Δt/Δτ and L/L₀. An approaching clock’s pulses can arrive faster because the signal distance shrinks; distinguish pulse arrival rate from corrected coordinate time.'));
A(1,'Explore speed and the classical limit',relativityLab()+P('At low speeds γ is nearly 1, so classical results are a good approximation. Near c, a small increase in β produces a large increase in γ.'),'interactive');
A(2,'Worked spacecraft: identify proper time',P('A spacecraft travels at 0.60c relative to Earth. Its onboard clock records 4.00 years between departure and arrival. Find the Earth-frame interval, treating the coasting segment as inertial.')+frames()+P('The two events happen at the same ship-clock location, so 4.00 years is Δτ.'),'worked');
A(2,'Worked spacecraft: compute the interval',E('γ = 1.25<br>Δt = 1.25(4.00) = 5.00 years')+P('Earth assigns a longer interval. The spacecraft clock does not malfunction; each frame uses its own time measurement.'),'worked');
A(2,'Worked spacecraft: recover the distance',E('Earth-frame distance = vΔt = 0.60c × 5.00 years = 3.00 light-years')+P('In the ship frame, the endpoint separation is contracted: 3.00/1.25 = 2.40 light-years. At 0.60c this passes in 4.00 years, agreeing with its clock.'),'worked');
A(2,'Worked spacecraft: reverse the known interval',P('If instead Earth measures 4.00 years for the same relative speed, the spacecraft interval is the unknown proper time.')+E('Δτ = Δt/γ = 4.00/1.25 = 3.20 years')+P('The number alone does not determine the operation. The frame and proper-time identification determine it.'),'worked');
A(2,'Worked ruler: moving spacecraft length',P('A ship has rest length 150 m and moves lengthwise at 0.80c relative to Earth.')+E('γ = 1/√(1 − 0.80²) = 1.66667…<br>L = 150/γ = 90.0 m')+P('The proper length is 150 m because it is measured at rest with the ship.'),'worked');
A(2,'Worked ruler: solve for speed',P('An object is measured at 60.0% of its proper longitudinal length. Find the relative speed.')+E('L/L₀ = √(1 − β²) = 0.600<br>β = √(1 − 0.600²) = 0.800<br>|v| = 0.800c')+P('This gives speed magnitude. Contraction alone does not tell whether the object approaches or recedes.'),'worked');
A(2,'Worked particle: identify the lifetime',P('A particle has proper mean lifetime 2.20 μs and travels at 0.980c relative to a detector. Estimate its Earth-frame mean travel distance.')+muon()+E('γ = 1/√(1 − 0.980²) ≈ 5.03'),'worked');
A(2,'Worked particle: dilated distance',E('Δt = γΔτ ≈ 11.1 μs<br>d = vΔt ≈ 3.25 × 10³ m')+P('Using vΔτ directly in the Earth frame would mix a velocity from one frame with an interval from another. The calculation predicts a mean distance, not an identical decay point for every particle.'),'worked');
A(2,'Worked particle: reconcile its rest frame',E('Lmoving = (3.25 × 10³)/γ ≈ 647 m<br>vΔτ = 0.980c(2.20 μs) ≈ 647 m')+P('In the particle frame the detector approaches through a contracted distance. Both descriptions predict the same meeting event. This is one of the important physical checks.'),'worked');
A(3,'Guided: which interval is proper?',H.check('proper','Creation and decay occur at one location in the particle’s rest frame. Its proper lifetime is measured…',['by that particle’s rest-frame clock','only by Earth','by dividing every interval by c'],0,['Correct. The events are colocated in the particle rest frame.','Earth sees the particle move between the events.','Proper time is an interval, not distance divided arbitrarily.']),'practice');
A(3,'Guided: a receding ship',P('A receding ship moves at 0.80c. Its clock records 6.00 s between two ticks at the same onboard location. Find the Earth-frame interval.')+number('recedetime','Earth interval',10,'s','γ = 1/0.600 = 1.66667. Δt = γΔτ = 10.0 s. Recession does not change the squared-speed factor.',.05),'practice');
A(3,'Guided: an approaching ship',P('A ship approaches at 0.80c and has proper length 120 m along its motion. Find its length measured in the Earth frame.')+number('approachL','Earth length',72,'m','L = L₀√(1 − β²) = 120 × 0.600 = 72.0 m. Direction does not change the contraction factor.',.2),'practice');
const q1={q:'A spacecraft has proper length 200 m and moves lengthwise at 0.60c relative to Earth. Its onboard clock records 8.00 s between events at the same onboard location. Find Earth-measured length and time interval, and explain what changes if the direction reverses.',points:['γ = 1/√(1 − 0.60²) = 1.25.','Moving length L = 200/1.25 = 160 m.','8.00 s is proper time because both events occur at one ship-clock position.','Earth interval = 1.25 × 8.00 = 10.0 s.','Reversing direction at the same speed magnitude leaves γ, contraction and coordinate time dilation unchanged; arriving-signal behaviour is a separate issue.']};
const q2={q:'A particle’s proper mean lifetime is 1.00 μs. It travels at 0.800c relative to a laboratory. Find its mean laboratory travel distance and reconcile this with the particle-frame distance travelled by the detector.',points:['γ = 1/√(1 − 0.800²) = 1.66667.','Laboratory mean lifetime = 1.66667 μs.','Laboratory mean distance = 0.800 × 3.00 × 10⁸ × 1.66667 × 10⁻⁶ = 400 m.','Particle-frame detector distance = 400/γ = 240 m.','0.800c × proper lifetime 1.00 μs = 240 m, so both frame descriptions agree.']};s.practice=[q1,q2];
A(3,'Independent: direction and proper quantities',question(q1),'practice');
A(3,'Independent: a particle and detector',question(q2),'practice');
A(3,'Why reciprocal clock statements do not conflict',P('Each inertial frame can describe the other’s moving clocks as slow, but they use different simultaneity conventions when comparing separated clocks. Comparing one pair of events consistently avoids mixing those measurements.'));
A(3,'A return journey needs a frame change',P('A traveller who turns around is not in one inertial frame for the whole round trip. The simple reciprocal-coasting argument cannot alone establish equal elapsed ages at reunion. For a specified itinerary, add proper times for its segments and handle the turnaround.'));
A(3,'Simultaneity is part of the model',P('Events at separated places that are simultaneous in one inertial frame need not be simultaneous in another. This is why a moving-length measurement specifies both end positions at the same time in the measuring frame.'));
A(3,'Avoid a false explanation about broken clocks',P('Time dilation is a relation between measurements, not damage to a clock or a slower mechanism. It applies to properly functioning clocks and particle lifetimes. All local processes in a frame use that frame’s time.'));
A(3,'Your relativity scenario reference',E('γ = 1/√(1 − β²)<br>Δt = γΔτ; L = L₀/γ')+P('Name the two frames, identify colocated events for proper time, identify the object rest frame for proper length, contract only along motion, and keep measurements from a single frame together in distance calculations.'));
s.mc('Proper time is measured between events…',['at the same position in the clock rest frame','simultaneous everywhere','only on Earth'],0,'A clock present at both events records their proper interval.');s.mc('At 0.60c, γ is…',['0.80','1.25','0.60'],1,'γ = 1/√0.64 = 1.25.');s.mc('Changing v from +0.80c to −0.80c changes γ…',['to its negative','not at all','to zero'],1,'The Lorentz factor depends on v².');s.mc('A proper length 120 m at 0.80c along its length is measured…',['200 m','120 m','72.0 m'],2,'L = L₀√(1 − β²) = 72.0 m.');s.mc('To find laboratory particle travel distance, use…',['lab velocity and lab time','lab velocity and proper time without adjustment','proper length times γ twice'],0,'Distance = velocity × time requires consistent frame measurements.');s.mc('Approaching pulse arrival rate and corrected coordinate time dilation are…',['automatically the same','different measurements that must be distinguished','both independent of signal travel'],1,'Arrival signals include changing light-travel distances.');s.finish();
}
