{
const s=make('relativistic-velocity-addition','relativity-foundations','Relativity: approaching, receding and overtaking','Velocity scenarios','Use signed velocities and distinguish a frame measurement from a closing rate.'),A=s.add;s.constants='Core 2026 velocity-transformations. Use c = 3.00 × 10⁸ m/s. One-dimensional inertial frames; +x to the right.';
const betaPrime=(u,v)=>(u-v)/(1-u*v),betaLab=(up,v)=>(up+v)/(1+up*v);
function ships(u=.6,v=-.6){const left=230,right=520;return marker('Ground-frame velocity arrows for two spacecraft; plus x is right',line(65,310,710,310)+'<rect x="'+(left-60)+'" y="150" width="120" height="65" rx="20" fill="#e8f5ef" stroke="#0b8774"/><rect x="'+(right-60)+'" y="150" width="120" height="65" rx="20" fill="#e6eff7" stroke="#2a6bb2"/>'+arrow(left,250,left+(u>=0?100:-100),250,'#0b8774')+arrow(right,250,right+(v>=0?100:-100),250,'#2a6bb2')+text(left,135,'A: '+(u>=0?'+':'')+u+'c','#0b8774','middle')+text(right,135,'B: '+(v>=0?'+':'')+v+'c','#2a6bb2','middle')+text(70,45,'Both arrows are velocities measured in S: Earth')+text(70,380,'Transform to an observer frame before calling a value')+text(70,415,'the object’s velocity measured by that observer.'));}
function velocityLab(){return '<div class="pp-sim" data-vel-lab><div class="pp-sim-controls"><label>Object velocity in S, u/c <input data-vu type="range" min="-95" max="95" value="60" step="5"><output data-vul></output></label><label>Observer velocity in S, v/c <input data-vv type="range" min="-95" max="95" value="-60" step="5"><output data-vvl></output></label></div><div data-vscene></div><div class="pp-sim-readout pp-scenario-readout" aria-live="polite"></div><p>Both starting velocities belong to Earth frame S. The transformed velocity belongs to the observer’s frame S′.</p></div>';}
const previous=s.wire;s.wire=root=>{previous(root);root.querySelectorAll('[data-vel-lab]').forEach(el=>{function update(){const u=+el.querySelector('[data-vu]').value/100,v=+el.querySelector('[data-vv]').value/100;el.querySelector('[data-vul]').textContent=u.toFixed(2)+'c';el.querySelector('[data-vvl]').textContent=v.toFixed(2)+'c';el.querySelector('[data-vscene]').innerHTML=ships(u,v);el.querySelector('.pp-sim-readout').textContent='Earth-coordinate velocity difference: '+(u-v).toFixed(3)+'c · object velocity in observer frame: '+betaPrime(u,v).toFixed(3)+'c';}el.querySelectorAll('input').forEach(i=>i.oninput=update);update();});};
A(0,'First distinguish two kinds of question',N('Core relativity scenario','The current 2026 syllabus and formula booklet include both velocity transformations. Learn the frame labels and signs before substituting.')+P('“How quickly does the distance between two ships change in Earth coordinates?” and “What velocity does one ship measure for the other?” ask different questions.'));
A(0,'Choose the observer before choosing signs',ships()+P('Take Earth as S. A moves right at +0.60c and B moves left at −0.60c. To find A’s velocity in B’s rest frame, treat B as the moving observer S′.'));
A(0,'Velocity needs a frame label',E('u = object velocity in S<br>v = S′ observer velocity in S<br>u′ = object velocity in S′')+P('Both inputs to the transformation must be measured in the same starting frame. The output is measured in a different frame.'));
A(0,'Approaching depends on positions too',P('Two oppositely directed arrows may describe approaching or receding objects depending on which object is on the left. The signed velocities determine the transformation; positions determine whether their separation grows or shrinks.'));
A(0,'Set one common positive direction',E('+x is right in both S and S′')+P('Do not reverse the axis halfway through a calculation. A negative transformed answer means motion leftwards in the chosen observer frame, not negative speed.'));
A(0,'Closing rate is a coordinate separation rate',P('In Earth coordinates two ships approaching at 0.60c each have a separation decreasing at 1.20c. This is not the velocity of either ship measured in the other’s rest frame and does not represent a signal travelling at 1.20c.'));
A(0,'Classical subtraction is an approximation',E('Low speed: u′ ≈ u − v')+P('At everyday speeds the correction term uv/c² is tiny. At speeds close to c, subtraction alone can predict an invalid object speed in another inertial frame.'));
A(1,'Transform from Earth to the moving observer',E('u′ = (u − v)/(1 − uv/c²)')+P('The minus signs follow the chosen definition: subtract the observer’s signed Earth velocity from the object’s signed Earth velocity, and keep the signed product in the denominator.'));
A(1,'Use fractions of c to simplify',E('β′ = (βu − βv)/(1 − βuβv)')+P('If u = 0.60c and v = −0.60c, use 0.60 and −0.60 inside the dimensionless fraction. Multiply the final fraction by c only if SI units are requested.'));
A(1,'Transform in the other direction',E('u = (u′ + v)/(1 + u′v/c²)')+P('Use this when the object velocity is known aboard the ship and the ship velocity is known relative to Earth. It has a plus sign because it is the inverse transformation.'));
A(1,'Use the same formula for both directions',P('There is no separate physical law for moving towards and moving away. Assign signs, define the observer and insert them into one transformation. The product uv can be positive or negative.'));
A(1,'Opposite signs change the denominator',E('u = +0.60c, v = −0.60c<br>1 − uv/c² = 1 − (−0.36) = 1.36')+P('Dropping the negative sign would produce 0.64 and an incorrect superluminal result. Write the signed substitution before calculating.'));
A(1,'Same signs give an overtaking problem',E('u = +0.80c, v = +0.60c<br>β′ = (0.80 − 0.60)/(1 − 0.48)')+P('The object is faster than the observer in the Earth frame, so the transformed answer is rightward. It is not simply 0.20c at these speeds.'));
A(1,'Explore signed transformations',velocityLab()+P('Try equal velocities, opposite velocities, and an observer faster than the object. Check the sign and verify that material-object outputs remain below c.'),'interactive');
A(2,'Worked approach: define the observer',P('In Earth frame S, A is left of B and moves right at +0.60c. B moves left at −0.60c. Find A’s velocity measured in B’s rest frame.')+ships(.6,-.6)+P('Object u = +0.60c; observer v = −0.60c.'),'worked');
A(2,'Worked approach: substitute signs',E('u′/c = [0.60 − (−0.60)]/[1 − (0.60)(−0.60)]<br>= 1.20/1.36 = +0.882')+P('B measures A moving rightward at 0.882c. Earth’s closing rate is 1.20c, but it is a different quantity.'),'worked');
A(2,'Worked recession: reverse the arrows',P('A is left of B and moves left at −0.60c; B moves right at +0.60c. Find A’s velocity in B’s frame.')+ships(-.6,.6)+E('u′/c = [−0.60 − 0.60]/[1 − (−0.60)(0.60)] = −0.882')+P('The relative speed is still 0.882c, now leftward and receding. Speed is the positive magnitude of signed velocity.'),'worked');
A(2,'Worked overtaking: same direction',P('A moves at +0.80c and B at +0.60c relative to Earth. Find A’s velocity in B’s frame.')+ships(.8,.6)+E('u′/c = (0.80 − 0.60)/(1 − 0.80 × 0.60)<br>= 0.20/0.52 = +0.385')+P('A overtakes B. Classical subtraction gives 0.20c, which is only the Earth-coordinate velocity difference.'),'worked');
A(2,'Worked faster observer: negative output',P('An object moves at +0.40c and the observer at +0.70c relative to Earth.')+E('u′/c = (0.40 − 0.70)/(1 − 0.28)<br>= −0.30/0.72 = −0.417')+P('In the observer frame the object moves backwards at 0.417c. A negative answer is physically meaningful.'),'worked');
A(2,'Worked launch aboard a ship',P('A ship moves at +0.60c relative to Earth and launches a probe forwards at +0.50c in the ship frame. Find the probe Earth velocity.')+E('u/c = (0.50 + 0.60)/(1 + 0.50 × 0.60)<br>= 1.10/1.30 = +0.846')+P('Use the forward transformation because the probe velocity is originally given aboard the ship.'),'worked');
A(2,'Worked backward launch aboard a ship',P('The same ship launches a probe backwards at −0.50c in its own frame.')+E('u/c = (−0.50 + 0.60)/(1 − 0.30)<br>= 0.10/0.70 = +0.143')+P('The probe still moves rightward relative to Earth. “Backwards aboard the ship” does not necessarily mean backwards in the Earth frame.'),'worked');
A(2,'Worked light signal: invariance check',E('u′ = c → u = (c + v)/(1 + v/c) = c')+P('The same result holds for a forward light signal from a moving ship. For u′ = −c the output is −c. The measured vacuum speed remains c in either direction.'),'worked');
A(3,'Guided: two receding ships',P('In Earth frame, object A moves at −0.50c and observer B at +0.50c. Find A’s signed velocity in B’s frame.')+number('recede-b','u′/c',-.8,'','(−0.50 − 0.50)/(1 − (−0.50)(0.50)) = −1.00/1.25 = −0.800.',.005),'practice');
A(3,'Guided: equal velocities',P('Object and observer both move at +0.75c relative to Earth. Find object velocity relative to the observer.')+number('sameb','u′/c',0,'','The numerator u − v is zero. They are at rest relative to each other.',.001),'practice');
A(3,'Guided: choose the transformation',H.check('whichtrans','Probe velocity is given aboard a ship; ship velocity is given relative to Earth. To find the probe Earth velocity, use…',['(u′ + v)/(1 + u′v/c²)','u − v without correction','(u − v)/(1 − uv/c²) with inputs from mixed frames'],0,['Correct: transform from the ship to Earth.','At high speeds classical addition is inadequate.','The inverse formula expects both inputs in S, not one from each frame.']),'practice');
const q1={q:'In Earth frame, spacecraft A travels right at +0.70c and spacecraft B travels left at −0.40c. A is initially left of B. Find A’s velocity measured by B and the Earth-coordinate closing rate. Explain the distinction.',points:['Define u = +0.70c and observer v = −0.40c.','u′ = (u − v)/(1 − uv/c²).','u′/c = 1.10/(1 + 0.28) = +0.859.','Earth-coordinate separation decreases at 0.70c + 0.40c = 1.10c.','Closing rate uses Earth distances and Earth times; 0.859c is the velocity measured in B’s rest frame.']};
const q2={q:'A spacecraft moves at +0.80c relative to Earth. A probe moves backwards at −0.60c in the spacecraft frame. Find its Earth velocity. Verify by transforming back into the ship frame.',points:['Forward transformation: u = (u′ + v)/(1 + u′v/c²).','u/c = (−0.60 + 0.80)/(1 − 0.48) = +0.384615… ≈ +0.385.','The probe remains rightward in the Earth frame, although it moves backwards aboard the ship.','Inverse check: (0.384615… − 0.80)/(1 − 0.384615… × 0.80) = −0.600.']};s.practice=[q1,q2];
A(3,'Independent: approach and closing rate',question(q1),'practice');
A(3,'Independent: backwards aboard a ship',question(q2),'practice');
A(3,'Convert a fraction of c into SI units',E('0.385c ≈ 0.385 × 3.00 × 10⁸ = 1.15 × 10⁸ m/s')+P('Use the unrounded fraction if it came from a calculation. Do not insert c a second time into a dimensionless β transformation.'));
A(3,'Recover an unknown ship velocity',P('If u and u′ are known, rearrange the forward transformation.')+E('v = (u − u′)/(1 − uu′/c²)')+P('The algebra has the same form as an inverse transformation. Define each frame before using it so that a familiar-looking equation does not hide mixed inputs.'));
A(3,'The low-speed check',P('For u = 20 m/s and v = 10 m/s, uv/c² ≈ 2.22 × 10⁻¹⁵. The denominator differs from 1 by a negligible amount and u′ ≈ 10 m/s. The relativistic relationship agrees with everyday relative motion in its valid limit.'));
A(3,'Diagnose an impossible material-object result',P('If both input speeds are less than c but the transformed material-object speed exceeds c, check the signs, denominator and frame definitions. A closing rate above c can be valid; calling it an observer-measured object speed is the error.')+paper('Diagnose 1.20c as the answer to the worked approach'));
A(3,'Your signed-velocity reference',E('S → S′: u′ = (u − v)/(1 − uv/c²)<br>S′ → S: u = (u′ + v)/(1 + u′v/c²)')+P('Label object, observer and frame; choose one positive direction; substitute signed values; interpret sign; distinguish closing rate; check a reverse transformation. These transformations are part of the current 2026 core pathway.'));
s.mc('The inverse transformation expects u and v to be measured…',['in the same starting frame','in whichever frames are available','only in the object frame'],0,'u is the object and v the observer velocity in S.');s.mc('Two ships each at 0.60c approach in Earth frame. One measures the other’s speed as…',['1.20c','0.882c','0.36c'],1,'1.20/1.36 = 0.882; 1.20c is the Earth-coordinate closing rate.');s.mc('A negative u′ means…',['negative speed is impossible','motion in the negative chosen direction','the denominator must be discarded'],1,'Velocity carries direction; speed is its magnitude.');s.mc('For a light signal emitted forwards from a moving ship, Earth measures vacuum speed…',['c + v','c','less than c'],1,'The transformation preserves c.');s.mc('A backward probe launch aboard a ship means its Earth velocity…',['must be negative','can still be positive','must equal zero'],1,'Frame transformation can give positive Earth velocity despite negative ship velocity.');s.mc('Relativistic velocity-transform equations in this site’s 2026 pathway are…',['included with explicit frame and sign conventions','a replacement for all time-dilation lessons','ordinary speed addition'],0,'The current 2026 syllabus and formula booklet include both transformations; frame labels and signed velocities remain essential.');s.finish();
}
// Explain authentic historical-paper examples in the relevant scenario lesson.
function insertExam(id,newPages){const spec=C.registry.find(s=>s.id===id);const at=spec.pages.findIndex(p=>p.chapter===3);spec.pages.splice(at,0,...newPages.map(([title,body])=>({chapter:2,title,html:'<div class="pp-page">'+body+'</div>',type:'worked'})));const sub=spec.pages.length+' sections · labelled models · explained scenarios · guided practice';const entry=window.PhysicsFocused.lessons.find(e=>e.id===id);entry.subtitle=sub;for(const groups of Object.values(window.PhysicsFocused.sequences[12]))for(const g of groups){const tile=g.lessons.find(e=>e.id===id);if(tile)tile.subtitle=sub;}}
function hookDiagram(){return marker('Hanging-basket hook: top screw horizontal force, lower pin components, basket weight and unknown hook centre of mass',line(140,70,140,320)+line(140,210,610,210)+ball(140,110,6)+ball(140,210,6)+arrow(140,110,55,110,'#2a6bb2')+arrow(140,210,245,210,'#0b8774')+arrow(140,210,140,140,'#0b8774')+arrow(310,235,310,315,'#c87518')+arrow(550,235,550,315,'#a15bb5')+text(180,65,'Screw pulls left: 68.5 N')+text(180,110,'Pin-to-screw: 9.70 cm')+text(180,170,'Bottom pin: Rₓ, Rᵧ')+text(235,350,'hook: 0.475g at x = ?')+text(460,380,'basket: 5.70g')+text(220,415,'Basket weight line is 11.6 cm from wall. Schematic.'));}
const hookSource='<p class="pp-source">West Australian Test Papers · 2024 Units 3/4 · Question 12. Source dimensions transcribed; explanatory working reconstructed from the stated data.</p>';
insertExam('static-equilibrium-focus-2',[
['Past exam: the nonuniform basket hook',hookSource+P('A 5.70 kg basket hangs from a nonuniform 0.475 kg hook. The basket weight line is 11.6 cm from the wall. A top screw 9.70 cm above the lower pin pulls horizontally left with 68.5 N. Find the hook centre of mass and the lower pin force.')+hookDiagram()+paper('Draw the system and convert centimetres to metres')],
['Past exam: choose the lower pin as pivot',hookSource+P('The lower pin forces have zero lever arm about the pin. The top screw creates anticlockwise torque. The two weights create clockwise torques with different horizontal arms.')+E('68.5(0.0970) − (5.70g)(0.116) − (0.475g)x = 0')],
['Past exam: solve the unknown centre of mass',hookSource+E('x = [68.5(0.0970) − 5.70(9.80)(0.116)]/[0.475(9.80)]<br>x = 0.0354 m = 3.54 cm')+P('The hook is nonuniform, so its centre cannot be assumed to be at the midpoint. Convert the lever arms to metres before calculating moments.')],
['Past exam: reconstruct the pin vector',hookSource+E('Rₓ = 68.5 N right<br>Rᵧ = (5.70 + 0.475)g = 60.515 N up<br>R = √(Rₓ² + Rᵧ²) = 91.4 N')+P('Angle to the vertical = atan(Rₓ/Rᵧ) = 48.5° right of vertical. The ratio differs from an angle measured from horizontal.')],
['Past exam: move the basket inward',hookSource+P('The basket weight is unchanged, but its torque arm decreases. The required screw force decreases. The vertical pin component remains 60.515 N while its horizontal component decreases; the resultant magnitude and angle from vertical both decrease.')+paper('Explain the sequence: smaller arm → screw force → pin vector')]
]);
const kaonSource='<p class="pp-source">West Australian Test Papers · 2024 Units 3/4 · Question 14(d), relativity excerpt. Other particle-physics subparts are covered separately.</p>';
insertExam('relativity-clock-length-scenarios',[
['Past exam: kaon lifetime and speed',kaonSource+P('A kaon has mean lifetime at rest 1.24 × 10⁻⁸ s. Stationary Earth observers measure 1.55 × 10⁻⁸ s. Calculate its speed as a fraction of c. (3 marks)')+paper('Identify proper time before choosing an equation')],
['Past exam: use the lifetime ratio',kaonSource+E('Δτ = 1.24 × 10⁻⁸ s; Δt = 1.55 × 10⁻⁸ s<br>γ = Δt/Δτ = 1.25')+P('The shorter rest-frame lifetime is proper time. The powers of ten cancel because both intervals use the same unit.')],
['Past exam: isolate speed rather than guess',kaonSource+E('1/γ² = 1 − v²/c²<br>v/c = √(1 − 1/γ²)<br>v/c = √(1 − 1/1.25²) = 0.600')+P('The lifetime ratio gives speed magnitude. It cannot identify whether the particle approaches or recedes.')],
['Past exam: three marking decisions',kaonSource+table(['Identify γ = Δt/Δτ = 1.25.','Use γ = 1/√(1 − v²/c²) and rearrange consistently.','Report v = 0.600c, a speed below c.'])+P('Explain each decision, then attempt the independent particle question with different values.')]
]);
